export function LektorMarketplace() {
  const { theme, setTheme } = useTheme()
  const [activeTab, setActiveTab] = useState<"catalog" | "scan" | "detail" | "auth" | "profile" | "checkout">("catalog")
  const [isAuthenticated, setIsAuthenticated] = useState(false)
  const [authPrompt, setAuthPrompt] = useState<"sell" | "buy" | null>(null)
  const [userName, setUserName] = useState("OtakuStore99")
  const [sellerTab, setSellerTab] = useState<"published" | "sales" | "purchases">("published")
  const [search, setSearch] = useState("")
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [selectedFilters, setSelectedFilters] = useState<string[]>([])
  const [favorites, setFavorites] = useState<number[]>([])
  const [showFavoritesOnly, setShowFavoritesOnly] = useState(false)
  const [selectedProduct, setSelectedProduct] = useState(products[0])
  const [scanSuccess, setScanSuccess] = useState(false)
  const [published, setPublished] = useState(false)
  const [buyerReview, setBuyerReview] = useState<{ rating: number; comment: string } | null>(null)

  const filteredProducts = useMemo(() => products.filter((product) => {
    const query = search.toLowerCase()
    const matchesSearch = !query || [product.title, product.author, product.publisher].some((value) => value.toLowerCase().includes(query))
    const matchesFilters = selectedFilters.length === 0 || selectedFilters.some((filter) => [product.category, product.publisher, product.condition.split(" - ")[0]].includes(filter))
    return matchesSearch && matchesFilters && (!showFavoritesOnly || favorites.includes(product.id))
  }), [search, selectedFilters, showFavoritesOnly, favorites])

  const goDetail = (product: (typeof products)[number]) => {
    setSelectedProduct(product)
    setActiveTab("detail")
    window.scrollTo({ top: 0, behavior: "smooth" })
  }

  const toggleFilter = (value: string) => setSelectedFilters((current) => current.includes(value) ? current.filter((item) => item !== value) : [...current, value])

  return (
    <div className="min-h-screen bg-background text-foreground">
      <header className="sticky top-0 z-40 border-b bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/80">
        <div className="mx-auto flex h-16 max-w-7xl items-center gap-3 px-4 md:gap-6 md:px-8">
          <button type="button" onClick={() => setActiveTab("catalog")} className="flex shrink-0 items-center gap-2" aria-label="Ir al catálogo">
            <span className="flex size-9 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"><BookOpen className="size-5" /></span>
            <span className="hidden text-lg font-bold tracking-tight sm:inline">LEKTOR</span>
          </button>
          <div className="relative flex-1 md:max-w-xl md:mx-auto">
            <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input value={search} onChange={(event) => { setSearch(event.target.value); setActiveTab("catalog") }} placeholder="Busca mangas, cómics o libros..." className="h-10 rounded-xl bg-muted/60 pl-9" />
          </div>
          <Button variant="ghost" size="icon" onClick={() => setTheme(theme === "dark" ? "light" : "dark")} aria-label="Cambio de Tema">{theme === "dark" ? <Sun data-icon="inline-start" /> : <Moon data-icon="inline-start" />}</Button>
          <div className="hidden items-center gap-2 md:flex">
            <Button variant="ghost" onClick={() => setActiveTab(isAuthenticated ? "profile" : "auth")}> <UserCircle data-icon="inline-start" /> Mi Perfil</Button>
            <Button onClick={() => isAuthenticated ? setActiveTab("scan") : setAuthPrompt("sell")}><Tag data-icon="inline-start" /> Vender un Artículo</Button>
          </div>
          <Button variant="ghost" size="icon" className="md:hidden" onClick={() => isAuthenticated ? setActiveTab("scan") : setAuthPrompt("sell")} aria-label="Vender un tomo"><Tag /></Button>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 py-6 md:px-8 md:py-10">
        {activeTab === "catalog" && <CatalogView products={filteredProducts} filtersOpen={filtersOpen} setFiltersOpen={setFiltersOpen} selectedFilters={selectedFilters} toggleFilter={toggleFilter} clearFilters={() => setSelectedFilters([])} showFavoritesOnly={showFavoritesOnly} setShowFavoritesOnly={setShowFavoritesOnly} favorites={favorites} toggleFavorite={(id) => setFavorites((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id])} onDetail={goDetail} />}
        {activeTab === "scan" && <ScanView scanSuccess={scanSuccess} setScanSuccess={setScanSuccess} published={published} setPublished={setPublished} onBack={() => setActiveTab("catalog")} />}
        {activeTab === "detail" && <DetailView product={selectedProduct} onBack={() => setActiveTab("catalog")} onBuy={() => isAuthenticated ? setActiveTab("checkout") : setAuthPrompt("buy")} />}
        {activeTab === "checkout" && <CheckoutView product={selectedProduct} onBack={() => setActiveTab("detail")} onSuccess={() => { setSellerTab("purchases"); setActiveTab("profile"); toast.success("¡Pago confirmado!", { description: "Tu compra quedó registrada en Mis Compras." }) }} />}
        {activeTab === "auth" && <AuthView onSuccess={(name) => { setUserName(name); setIsAuthenticated(true); setActiveTab("profile") }} onBack={() => setActiveTab("catalog")} />}
        {activeTab === "profile" && <SellerProfileView userName={userName} setUserName={setUserName} buyerReview={buyerReview} setBuyerReview={setBuyerReview} tab={sellerTab} setTab={setSellerTab} onBack={() => setActiveTab("catalog")} onLogout={() => { setIsAuthenticated(false); setActiveTab("auth") }} />}
        <Dialog open={authPrompt !== null} onOpenChange={(open) => !open && setAuthPrompt(null)}>
          <DialogContent className="rounded-2xl sm:max-w-md"><DialogHeader><DialogTitle>Inicia sesión para continuar</DialogTitle><DialogDescription>{authPrompt === "sell" ? "Crea tu perfil de lector para publicar tus tomos." : "Necesitas una cuenta para comprar de forma segura."}</DialogDescription></DialogHeader><div className="flex flex-col gap-3"><Button onClick={() => { setAuthPrompt(null); setActiveTab("auth") }}>Iniciar Sesión</Button><Button variant="outline" onClick={() => { setAuthPrompt(null); setActiveTab("auth") }}>Crear Cuenta</Button></div></DialogContent>
        </Dialog>
      </main>
    </div>
  )
}

function AuthView({ onSuccess, onBack }: { onSuccess: (name: string) => void; onBack: () => void }) {
  const [mode, setMode] = useState<"login" | "register">("login")
  const [showPassword, setShowPassword] = useState(false)
  const [email, setEmail] = useState("")
  const [password, setPassword] = useState("")
  const [name, setName] = useState("")
  const submit = (event: React.FormEvent) => { event.preventDefault(); onSuccess(mode === "register" ? name || "Nuevo lector" : "OtakuStore99"); toast.success(mode === "register" ? "Cuenta creada" : "Bienvenido de vuelta") }
  return <div className="flex min-h-[calc(100vh-9rem)] items-center justify-center bg-slate-50 py-8 dark:bg-slate-950"><Card className="w-full max-w-md rounded-2xl border-0 shadow-xl ring-1 ring-border/50"><CardHeader className="text-center"><div className="mx-auto mb-2 flex size-12 items-center justify-center rounded-2xl bg-primary text-primary-foreground"><BookOpen className="size-6" /></div><CardTitle className="text-2xl">Únete a LEKTOR</CardTitle><CardDescription>Tu próxima historia está a un intercambio de distancia.</CardDescription></CardHeader><CardContent><div className="mb-6 grid grid-cols-2 rounded-lg bg-muted p-1"><Button type="button" variant={mode === "login" ? "default" : "ghost"} onClick={() => setMode("login")} className="rounded-md">Iniciar Sesión</Button><Button type="button" variant={mode === "register" ? "default" : "ghost"} onClick={() => setMode("register")} className="rounded-md">Crear Cuenta</Button></div><form onSubmit={submit} className="flex flex-col gap-4">{mode === "register" && <div className="flex flex-col gap-2"><Label htmlFor="auth-name">Nombre de Usuario</Label><Input id="auth-name" value={name} onChange={(e) => setName(e.target.value)} placeholder="OtakuStore99" required /></div>}<div className="flex flex-col gap-2"><Label htmlFor="auth-email">Correo Electrónico</Label><Input id="auth-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="tu@email.com" required /></div><div className="flex flex-col gap-2"><div className="flex items-center justify-between"><Label htmlFor="auth-password">Contraseña</Label>{mode === "login" && <button type="button" className="text-xs text-primary hover:underline" onClick={() => toast.info("Te enviaremos un enlace de recuperación")}>¿Olvidaste tu contraseña?</button>}</div><div className="relative"><Input id="auth-password" type={showPassword ? "text" : "password"} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" required minLength={6} className="pr-10" /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground" aria-label="Mostrar contraseña">{showPassword ? <EyeOff className="size-4" /> : <Eye className="size-4" />}</button></div></div>{mode === "register" && <div className="flex flex-col gap-2"><Label htmlFor="auth-confirm">Confirmar Contraseña</Label><Input id="auth-confirm" type="password" placeholder="Repite tu contraseña" required minLength={6} /></div>}<Button type="submit" size="lg" className="mt-2 w-full rounded-xl">{mode === "login" ? <LogIn data-icon="inline-start" /> : <UserPlus data-icon="inline-start" />}{mode === "login" ? "Ingresar" : "Registrarse"}</Button></form><div className="my-6 flex items-center gap-3"><Separator className="flex-1" /><span className="text-xs text-muted-foreground">O continuar con</span><Separator className="flex-1" /></div><Button type="button" variant="outline" className="w-full rounded-xl" onClick={() => onSuccess("GoogleReader")}><span className="mr-2 font-bold text-primary">G</span> Continuar con Google</Button><Button type="button" variant="link" className="mt-3 w-full" onClick={onBack}>Volver al catálogo</Button></CardContent></Card></div>
}

