  const [shippingLabel, setShippingLabel] = useState(false)
  const [section, setSection] = useState<"posts" | "reservations" | "sales">("posts")
  return <div className="mx-auto flex max-w-5xl flex-col gap-8"><div className="flex items-center justify-between"><button type="button" onClick={onBack} className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="size-4" /> Volver al catálogo</button><Button variant="outline" size="sm" onClick={onLogout}>Cerrar sesión</Button></div><Card className="rounded-2xl border-0 bg-primary text-primary-foreground shadow-lg"><CardContent className="flex flex-col gap-5 p-6 sm:flex-row sm:items-center"><div className="flex size-20 items-center justify-center rounded-full bg-primary-foreground/15 text-2xl font-bold ring-4 ring-primary-foreground/10">{userName.slice(0, 2).toUpperCase()}</div><div className="flex-1"><p className="text-sm text-primary-foreground/70">Mi perfil</p><h1 className="text-3xl font-bold">{userName}</h1><p className="mt-1 text-sm text-primary-foreground/75">Miembro desde marzo de 2024</p></div><div className="flex items-center gap-2"><Star className="size-5 fill-amber-300 text-amber-300" /><span className="text-xl font-bold">4.9</span><span className="text-sm text-primary-foreground/70">(12 reseñas)</span></div></CardContent></Card><div className="flex flex-col gap-5"><div className="flex items-start gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-emerald-900 dark:border-emerald-900/50 dark:bg-emerald-950/30 dark:text-emerald-200"><CircleCheck className="mt-0.5 size-5" /><div><p className="font-semibold">¡Felicidades! Has vendido &apos;Chainsaw Man Vol. 1&apos;</p><p className="text-sm opacity-80">El pedido está listo para que lo prepares.</p></div></div><div className="grid w-full grid-cols-3 rounded-xl bg-muted p-1 sm:max-w-xl"><Button variant={section === "posts" ? "default" : "ghost"} onClick={() => setSection("posts")}>Mis Publicaciones <Badge variant="secondary" className="ml-2">3</Badge></Button><Button variant={section === "reservations" ? "default" : "ghost"} onClick={() => setSection("reservations")}>Mis Reservas <Badge variant="secondary" className="ml-2">2</Badge></Button><Button variant={section === "sales" ? "default" : "ghost"} onClick={() => setSection("sales")}>Ventas por Despachar <Badge variant="secondary" className="ml-2">1</Badge></Button></div>{section === "sales" ? <Card className="rounded-xl border-emerald-200"><CardHeader><CardTitle>Ventas por Despachar</CardTitle><CardDescription>Pedidos pagados pendientes de preparación.</CardDescription></CardHeader><CardContent><div className="flex flex-col gap-4 rounded-xl border bg-muted/30 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-semibold">Chainsaw Man Vol. 1</p><p className="text-sm text-muted-foreground">Pedido TT-2048 · pagado hoy</p></div><Badge className="bg-emerald-600 text-white">Pagado</Badge></div><Separator /><div className="grid gap-3 text-sm sm:grid-cols-2"><div><p className="font-medium">Comprador</p><p className="text-muted-foreground">Camila V. · camila@email.com</p></div><div><p className="font-medium">Dirección de envío</p><p className="text-muted-foreground">Av. Providencia 1234, Santiago</p></div></div><div className="flex flex-col gap-3"><div className="flex items-center justify-between text-xs font-medium"><span className="text-primary">Generado</span><span className="text-muted-foreground">En Tránsito</span><span className="text-muted-foreground">Entregado</span></div><Progress value={8} /><div className="rounded-lg border border-dashed bg-muted/30 p-3"><p className="mb-2 text-xs font-semibold text-muted-foreground">Herramientas de Simulación (Dev)</p><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => toast.success("Bluexpress escaneó el paquete: En Tránsito")}>Simular escaneo de Bluexpress (Drop-off)</Button><Button size="sm" variant="outline" onClick={() => toast.success("Tracking actualizado: Entregado")}>Simular entrega final al comprador</Button></div></div></div></div></CardContent></Card> : section === "posts" ? <Card className="rounded-xl"><CardHeader><CardTitle>Artículos a la venta</CardTitle><CardDescription>Gestiona tus historias publicadas en TomoTrade.</CardDescription></CardHeader><CardContent className="flex flex-col gap-3">{[["Chainsaw Man Vol. 1", "$9.500", "Activo"], ["Vagabond Vol. 1", "$8.000", "Activo"], ["Watchmen", "$12.000", "Pausado"]].map(([title, price, status]) => <div key={title} className="flex flex-wrap items-center gap-4 rounded-lg border p-4"><div className="flex size-14 items-center justify-center rounded-lg bg-muted"><BookOpen className="size-6 text-primary" /></div><div className="min-w-0 flex-1"><p className="font-semibold">{title}</p><p className="text-sm text-primary">{price} · <span className="text-muted-foreground">{status}</span></p></div><div className="flex gap-2"><Button variant="outline" size="sm" onClick={() => toast.info("Editor de publicación abierto")}><Pencil data-icon="inline-start" /> Editar</Button><Button variant="ghost" size="sm" onClick={() => toast.success("Publicación pausada")}><Pause data-icon="inline-start" /> Pausar</Button></div></div>)}</CardContent></Card> : <Card className="rounded-xl"><CardHeader><CardTitle>Artículos solicitados</CardTitle><CardDescription>Revisa el estado de tus reservas y compras.</CardDescription></CardHeader><CardContent className="flex flex-col gap-3">{[["Batman: The Long Halloween", "Pendiente de contacto", "En curso"], ["El nombre del viento", "Completado", "Listo"]].map(([title, status, tag]) => <div key={title} className="flex items-center gap-4 rounded-lg border p-4"><div className="flex size-12 items-center justify-center rounded-lg bg-muted"><ShoppingBag className="size-5 text-primary" /></div><div className="flex-1"><p className="font-semibold">{title}</p><p className="text-sm text-muted-foreground">{status}</p></div><Badge variant={tag === "Listo" ? "default" : "secondary"}>{tag === "Listo" ? <CircleCheck className="mr-1 size-3" /> : <Clock3 className="mr-1 size-3" />}{tag}</Badge></div>)}</CardContent></Card>}</div></div>
